declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('projects.view');
$pageTitle='Dashboard de proyectos';$pdo=db();
$stats=[
'active'=>(int)$pdo->query("SELECT COUNT(*) FROM projects WHERE status='active'")->fetchColumn(),
'planning'=>(int)$pdo->query("SELECT COUNT(*) FROM projects WHERE status='planning'")->fetchColumn(),
'at_risk'=>(int)$pdo->query("SELECT COUNT(*) FROM projects WHERE status IN ('planning','active','on_hold') AND health IN ('at_risk','off_track')")->fetchColumn(),
'overdue'=>(int)$pdo->query("SELECT COUNT(*) FROM project_tasks WHERE status<>'done' AND due_date<CURDATE()")->fetchColumn(),
'due7'=>(int)$pdo->query("SELECT COUNT(*) FROM project_tasks WHERE status<>'done' AND due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)")->fetchColumn(),
'hoursMonth'=>(float)$pdo->query("SELECT COALESCE(SUM(hours),0) FROM project_time_entries WHERE work_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')")->fetchColumn(),
];
$projects=$pdo->query("SELECT p.*,c.company_name,u.name owner_name,(SELECT COUNT(*) FROM project_tasks t WHERE t.project_id=p.id) task_count,(SELECT COUNT(*) FROM project_tasks t WHERE t.project_id=p.id AND t.status='done') done_count FROM projects p LEFT JOIN clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=p.owner_user_id WHERE p.status IN ('planning','active','on_hold') ORDER BY FIELD(p.health,'off_track','at_risk','on_track'),p.due_date IS NULL,p.due_date LIMIT 12")->fetchAll();
$statusRows=$pdo->query("SELECT status,COUNT(*) total FROM project_tasks GROUP BY status")->fetchAll();$statusLabels=[];$statusValues=[];foreach($statusRows as$r){$statusLabels[]=pm_task_status_label($r['status']);$statusValues[]=(int)$r['total'];}
$healthRows=$pdo->query("SELECT health,COUNT(*) total FROM projects WHERE status IN ('planning','active','on_hold') GROUP BY health")->fetchAll();$healthLabels=[];$healthValues=[];foreach($healthRows as$r){$healthLabels[]=pm_health_label($r['health']);$healthValues[]=(int)$r['total'];}
$workRows=$pdo->query("SELECT u.name,COALESCE(SUM(te.hours),0) hours FROM users u LEFT JOIN project_time_entries te ON te.user_id=u.id AND te.work_date>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) WHERE u.is_active=1 GROUP BY u.id,u.name HAVING hours>0 ORDER BY hours DESC LIMIT 10")->fetchAll();
$chart=['status'=>['labels'=>$statusLabels,'values'=>$statusValues],'health'=>['labels'=>$healthLabels,'values'=>$healthValues],'workload'=>['labels'=>array_column($workRows,'name'),'values'=>array_map('floatval',array_column($workRows,'hours'))]];
require __DIR__.'/includes/header.php';?>
