<div class="pm-kpis"><a class="stat-card" href="projects.php?status=active"><small>PROYECTOS ACTIVOS</small><strong><?=$stats['active']?></strong><span>En ejecución</span></a><a class="stat-card" href="projects.php?status=planning"><small>EN PLANIFICACIÓN</small><strong><?=$stats['planning']?></strong><span>Próximos a iniciar</span></a><a class="stat-card danger" href="projects.php?health=at_risk"><small>EN RIESGO</small><strong><?=$stats['at_risk']?></strong><span>Requieren atención</span></a><a class="stat-card danger" href="project_calendar.php?overdue=1"><small>TAREAS ATRASADAS</small><strong><?=$stats['overdue']?></strong><span>Fuera de plazo</span></a><a class="stat-card" href="project_calendar.php"><small>VENCEN EN 7 DÍAS</small><strong><?=$stats['due7']?></strong><span>Próximas entregas</span></a><a class="stat-card" href="project_timesheet.php"><small>HORAS DEL MES</small><strong><?=e(number_format($stats['hoursMonth'],1,',','.'))?></strong><span>Registradas</span></a></div>
<?php $activeRiskCount=(int)$pdo->query("SELECT COUNT(*) FROM project_risks WHERE status IN ('open','mitigating')")->fetchColumn();$modules=[['project_kanban.php','kanban','Kanban','Organiza tareas por estado y mueve el trabajo visualmente.'],['project_gantt.php','gantt','Gantt','Cronograma global, fechas, duración y dependencias.'],['project_calendar.php','calendar','Calendario','Entregas y compromisos con opciones para compartir.'],['project_timesheet.php','time','Horas y recursos','Carga de trabajo, facturables y rendimiento del equipo.'],['project_risks.php','risk','Riesgos','Probabilidad, impacto, mitigación y responsables.'],['project_expenses.php','billing','Costos','Gastos, categorías, facturables y control presupuestario.']];?>
